#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import {createHash} from 'node:crypto';
import {spawn} from 'node:child_process';

const root=path.resolve(import.meta.dirname,'..');
const cacheRoot=path.join(root,'.klipper-build-cache');
const targetRoot=path.join(cacheRoot,'target');
// SQLite and NSIS use legacy Windows path limits. Keep temporary paths short
// and separate each checkout without inheriting its full directory depth.
const tempRoot=process.platform==='win32'
  ?path.join(os.tmpdir(),'kf-build',createHash('sha256').update(root).digest('hex').slice(0,16))
  :path.join(cacheRoot,'temp');
const logRoot=path.join(cacheRoot,'logs');
const logPath=path.join(logRoot,'BUILD-AND-INSTALL.log');
const failurePath=path.join(logRoot,'BUILD-FAILURE.txt');
const installerRoot=path.join(root,'INSTALLER');
const rustVendor=path.join(root,'rv');
const rustArchive=path.join(root,'offline-tools','rust','rust-vendor-v1144.tar.gz');
const nsisArchive=path.join(root,'offline-tools','nsis','nsis-3.11.zip');
const nsisPlugin=path.join(root,'offline-tools','nsis','nsis_tauri_utils-0.5.3.dll');
const nsisTools=path.join(targetRoot,'.tauri','NSIS');
const tauriCli=path.join(root,'offline-tools','tauri-cli','node_modules','@tauri-apps','cli','tauri.js');
const offlineConfig=path.join(root,'src-tauri','tauri.offline.conf.json');
const manifestVerifier=path.join(root,'scripts','verify-release-manifest.ps1');
const releaseManifest=path.join(root,'MANIFEST-SHA256.txt');
const offlineManifest=path.join(root,'OFFLINE-PAYLOAD-SHA256.txt');
const cargoManifest=path.join(root,'src-tauri','Cargo.toml');
const buildIdFile=path.join(root,'RELEASE-BUILD-ID.txt');

const stages=[
  'required tools','package integrity','frontend payload','build cache fingerprint',
  'offline payload extraction','Cargo metadata',
  'Rust tests','Clippy','daemon sidecar','Windows IPC probe','NSIS build',
  'desktop binary checks','installer collection',
];

if(process.argv.includes('--self-test')){
  if(stages.length!==13||new Set(stages).size!==stages.length)throw new Error('clean installer stage inventory is invalid');
  for(const required of [rustArchive,nsisArchive,nsisPlugin,tauriCli,offlineConfig,manifestVerifier,releaseManifest,offlineManifest,cargoManifest,buildIdFile]){
    if(!fs.existsSync(required))throw new Error(`missing packaged input: ${path.relative(root,required)}`);
  }
  console.log(`R9.9 direct NSIS installer self-test OK: ${stages.length} linear stages, one entry point and one full log`);
  process.exit(0);
}

fs.mkdirSync(logRoot,{recursive:true});
const log=fs.createWriteStream(logPath,{flags:'w'});
let currentStage='initialization';

const write=(stream,text)=>{
  stream.write(text);
  log.write(text);
};
const out=text=>write(process.stdout,String(text));
const err=text=>write(process.stderr,String(text));
const line=text=>out(`${text}\n`);

class StageFailure extends Error{
  constructor(stage,command,exitCode){
    super(`${stage} failed with exit code ${exitCode}`);
    this.stage=stage;
    this.command=command;
    this.exitCode=exitCode;
  }
}

const cleanDisplay=(command,args)=>[command,...args].map(value=>String(value).includes(' ')?`"${value}"`:value).join(' ');
const run=(stage,command,args=[],options={})=>new Promise((resolve,reject)=>{
  currentStage=stage;
  const display=cleanDisplay(command,args);
  line(`\n[${stage}]`);
  line(`> ${display}`);
  const child=spawn(command,args,{
    cwd:options.cwd??root,
    env:options.env??buildEnv,
    shell:false,
    windowsHide:false,
    stdio:['inherit','pipe','pipe'],
  });
  child.stdout.on('data',chunk=>write(process.stdout,chunk));
  child.stderr.on('data',chunk=>write(process.stderr,chunk));
  child.once('error',error=>reject(new StageFailure(stage,`${display}: ${error.message}`,1)));
  child.once('close',(code,signal)=>{
    if(code===0)return resolve();
    reject(new StageFailure(stage,signal?`${display} (signal ${signal})`:display,Number.isInteger(code)?code:1));
  });
});

const runNode=(stage,relative,args=[])=>run(stage,process.execPath,[path.join(root,relative),...args]);

const ensureInsideRoot=candidate=>{
  const resolved=path.resolve(candidate);
  const prefix=`${root}${path.sep}`.toLowerCase();
  if(!resolved.toLowerCase().startsWith(prefix))throw new Error(`refusing path outside project: ${resolved}`);
  return resolved;
};
const removeOwned=candidate=>{
  const resolved=ensureInsideRoot(candidate);
  fs.rmSync(resolved,{recursive:true,force:true,maxRetries:5,retryDelay:100});
};
const requireFile=file=>{
  if(!fs.existsSync(file)||!fs.statSync(file).isFile())throw new StageFailure(currentStage,`missing ${path.relative(root,file)}`,1);
};
const findFiles=(directory,predicate)=>{
  if(!fs.existsSync(directory))return [];
  const found=[];
  for(const entry of fs.readdirSync(directory,{withFileTypes:true})){
    const absolute=path.join(directory,entry.name);
    if(entry.isDirectory())found.push(...findFiles(absolute,predicate));
    else if(entry.isFile()&&predicate(absolute))found.push(absolute);
  }
  return found;
};

const buildEnv={
  ...process.env,
  CARGO_HOME:path.join(cacheRoot,'cargo'),
  CARGO_TARGET_DIR:targetRoot,
  TEMP:tempRoot,
  TMP:tempRoot,
  CARGO_NET_OFFLINE:'true',
  CARGO_INCREMENTAL:'0',
  CARGO_PROFILE_RELEASE_DEBUG:'0',
  CARGO_PROFILE_RELEASE_INCREMENTAL:'false',
};
// Windows PowerShell 5.1 must build its own module path when launched by pwsh.
for(const name of Object.keys(buildEnv))if(name.toLowerCase()==='psmodulepath')delete buildEnv[name];

const verifyManifest=(kind,file)=>run(`${kind} manifest`, 'powershell.exe',[
  '-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass',
  '-File',manifestVerifier,'-ManifestPath',file,'-RootPath',root,'-Kind',kind,
]);

const closeLog=()=>new Promise(resolve=>log.end(resolve));

try{
  line('============================================================');
  line('  Klipper Farm v1.14.5 - R111 Restore R94 Native Upload');
  line('============================================================');
  line(`Project: ${root}`);
  line(`Full log: ${logPath}`);
  const buildId=fs.readFileSync(buildIdFile,'utf8').trim();
  if(!/^[A-Z0-9][A-Z0-9._-]{7,95}$/.test(buildId))throw new StageFailure('package integrity','RELEASE-BUILD-ID.txt is missing or malformed',1);
  line(`Release build ID: ${buildId}`);

  if(process.platform!=='win32'||process.arch!=='x64')throw new StageFailure('required tools',`requires win32-x64, found ${process.platform}-${process.arch}`,1);
  const [nodeMajor,nodeMinor]=process.versions.node.split('.').map(Number);
  if(nodeMajor<20||(nodeMajor===20&&nodeMinor<11))throw new StageFailure('required tools',`Node ${process.versions.node}; required 20.11+`,1);

  fs.mkdirSync(cacheRoot,{recursive:true});
  fs.mkdirSync(buildEnv.CARGO_HOME,{recursive:true});
  fs.mkdirSync(targetRoot,{recursive:true});
  fs.mkdirSync(tempRoot,{recursive:true});
  removeOwned(installerRoot);

  await run('required tools',process.execPath,['--version']);
  await run('required tools','cargo',['--version']);
  await run('required tools','rustc',['--version']);
  await run('required tools','cargo',['clippy','--version']);
  await run('required tools','tar',['--version']);
  await run('required tools','powershell.exe',['-NoLogo','-NoProfile','-NonInteractive','-Command','$PSVersionTable.PSVersion.ToString()']);

  const disk=fs.statfsSync(root);
  const freeBytes=Number(disk.bavail)*Number(disk.bsize);
  line(`Free space: ${Math.floor(freeBytes/1024/1024/1024)} GB`);
  if(freeBytes<12*1024**3)throw new StageFailure('required tools','at least 12 GB free space is required',2);

  currentStage='package integrity';
  for(const file of [rustArchive,nsisArchive,nsisPlugin,tauriCli,offlineConfig,manifestVerifier,releaseManifest,offlineManifest,cargoManifest,buildIdFile])requireFile(file);
  await verifyManifest('release',releaseManifest);
  await verifyManifest('offline',offlineManifest);
  await runNode('frontend payload','scripts/check-production-bundle.mjs');
  await runNode('build cache fingerprint','scripts/prepare-windows-build-cache.mjs');

  currentStage='offline payload extraction';
  const vendorMarker=path.join(rustVendor,'.kf-v1144-complete');
  if(!fs.existsSync(vendorMarker)){
    removeOwned(rustVendor);
    await run('offline payload extraction','tar',['-xzf',rustArchive,'-C',root]);
    requireFile(path.join(rustVendor,'serde-1.0.229','Cargo.toml'));
    fs.writeFileSync(vendorMarker,'verified\n');
  }
  const nsisExecutable=path.join(nsisTools,'makensis.exe');
  const nsisPluginTarget=path.join(nsisTools,'Plugins','x86-unicode','additional','nsis_tauri_utils.dll');
  if(!fs.existsSync(nsisExecutable)||!fs.existsSync(nsisPluginTarget)){
    removeOwned(nsisTools);
    removeOwned(path.join(targetRoot,'.tauri','nsis-3.11'));
    fs.mkdirSync(path.join(targetRoot,'.tauri'),{recursive:true});
    await run('offline payload extraction','powershell.exe',['-NoLogo','-NoProfile','-NonInteractive','-Command',
      '$ErrorActionPreference="Stop"; Expand-Archive -LiteralPath $env:KF_NSIS_ARCHIVE -DestinationPath (Join-Path $env:CARGO_TARGET_DIR ".tauri") -Force'],{
      env:{...buildEnv,KF_NSIS_ARCHIVE:nsisArchive},
    });
    fs.renameSync(path.join(targetRoot,'.tauri','nsis-3.11'),nsisTools);
    fs.mkdirSync(path.dirname(nsisPluginTarget),{recursive:true});
    fs.copyFileSync(nsisPlugin,nsisPluginTarget);
  }
  requireFile(nsisExecutable);
  requireFile(nsisPluginTarget);

  await run('Cargo metadata','cargo',['metadata','--offline','--locked','--manifest-path',cargoManifest,'--format-version','1','--no-deps']);
  await run('update cache cleanup','powershell.exe',['-NoLogo','-NoProfile','-NonInteractive','-File',path.join(root,'scripts','check-update-cache.ps1')]);
  await runNode('update gate','scripts/check-update-gate.mjs');
  await runNode('HTTP keep-alive regression','scripts/check-http-keepalive.mjs');
  await runNode('native upload regression','scripts/check-native-upload-runtime.mjs');
  await runNode('native REST RPC regression','scripts/check-native-rest-rpc-runtime.mjs');
  await runNode('Rust tests','scripts/run-rust-tests.mjs');
  await run('Clippy','cargo',['clippy','--offline','--locked','--workspace','--all-targets','--features','fault-injection','--manifest-path',cargoManifest]);

  await runNode('daemon sidecar','scripts/prepare-sidecar.mjs');
  await run('Windows IPC probe','cargo',['build','--offline','--locked','--release','--manifest-path',cargoManifest,'--bin','klipper-farm-ipc-probe']);

  await run('NSIS build',process.execPath,[tauriCli,'build','--bundles','nsis','--config',offlineConfig,'--ci']);
  const desktopExe=path.join(targetRoot,'release','klipper-farm-client.exe');
  const daemonExe=path.join(targetRoot,'release','klipper-farmd.exe');
  const probeExe=path.join(targetRoot,'release','klipper-farm-ipc-probe.exe');
  for(const file of [desktopExe,daemonExe,probeExe])requireFile(file);
  await runNode('desktop binary checks','scripts/check-windows-gui-binaries.mjs',[desktopExe,daemonExe]);
  await runNode('desktop binary checks','scripts/check-desktop-packaging.mjs',['--generated-root',path.join(targetRoot,'release','nsis')]);

  currentStage='installer collection';
  fs.mkdirSync(installerRoot,{recursive:true});
  const installers=findFiles(path.join(targetRoot,'release','bundle','nsis'),file=>file.toLowerCase().endsWith('.exe')).sort();
  if(!installers.length)throw new StageFailure(currentStage,'NSIS setup.exe was not found',1);
  for(const source of installers)fs.copyFileSync(source,path.join(installerRoot,path.basename(source)));
  const installer=path.join(installerRoot,path.basename(installers.at(-1)));

  line('\n============================================================');
  line('  BUILD SUCCESSFUL');
  line('============================================================');
  line(`Installer: ${installer}`);
  line(`Full log: ${logPath}`);
  await closeLog();
  if(!process.argv.includes('--build-only'))spawn(installer,[],{detached:true,stdio:'ignore',cwd:installerRoot}).unref();
  process.exitCode=0;
}catch(error){
  const failure=error instanceof StageFailure
    ? error
    : new StageFailure(currentStage,error instanceof Error?error.stack??error.message:String(error),1);
  const summary=[
    'BUILD AND INSTALL FAILED',
    `Stage: ${failure.stage}`,
    `Exit code: ${failure.exitCode}`,
    `Command/detail: ${failure.command}`,
    `Full log: ${logPath}`,
    '',
  ].join('\r\n');
  err(`\n============================================================\n  BUILD AND INSTALL FAILED\n============================================================\n`);
  err(`Stage: ${failure.stage}\nExit code: ${failure.exitCode}\nCommand/detail: ${failure.command}\n`);
  err(`Full log: ${logPath}\n`);
  fs.writeFileSync(failurePath,summary);
  await closeLog();
  process.exitCode=failure.exitCode||1;
}

import fs from 'node:fs';
import path from 'node:path';

const root=path.resolve(import.meta.dirname,'..');
const read=file=>fs.readFileSync(path.join(root,file),'utf8');
const assert=(condition,message)=>{if(!condition)throw new Error(message)};

const rust=`${read('src-tauri/src/lib.rs')}\n${read('src-tauri/src/discovery_commands.rs')}\n${read('src-tauri/src/moonraker_protocol.rs')}`;
const moonraker=read('src/lib/moonraker.ts');
const validation=read('src/lib/gcodeValidation.ts');
const analysis=read('src/lib/gcodeAnalysis.ts');
const queue=read('src/components/QueuePanel.tsx');
const dispatcher=read('src/components/AutoDispatchPanel.tsx');
const local=read('src/components/LocalLibraryPanel.tsx');
const notifications=read('src/components/NotificationCenter.tsx');
const temperatures=read('src/components/TemperatureChart.tsx');
const production=read('src/components/ProductionPanel.tsx');
const app=read('src/App.tsx');
const system=read('src/components/SystemPanel.tsx');
const index=read('dist/index.html');
const bundlePath=index.match(/src="\/(assets\/index-[^"]+\.js)"/)?.[1];
assert(bundlePath,'offline index does not reference a content-hashed JavaScript bundle');
const bundle=read(`dist/${bundlePath}`);

assert(/\[7125_u16,\s*80_u16\]\s*\.into_iter\(\)/.test(rust)&&rust.includes('struct DiscoveryTarget'),'native discovery does not preserve K1C port 80/7125 targets');
assert(rust.includes('moonraker_upload_begin')&&rust.includes('moonraker_upload_chunk')&&rust.includes('moonraker_upload_finish')&&rust.includes('moonraker_upload_abort'),'native Moonraker chunked upload lifecycle is incomplete');
assert(rust.includes('local_library_import_begin')&&rust.includes('local_library_read_begin')&&rust.includes('MAX_TRANSFER_SESSIONS'),'native local-library streaming sessions or bounds are missing');
assert(rust.includes('upload_verified_file_to_moonraker_blocking')&&rust.includes('expected_sha256'),'local-to-printer transfer is not verified against its streamed hash');

assert(moonraker.includes('requestScheduler.run')&&moonraker.includes("requestScheduler.run('upload'")&&moonraker.includes('runBackgroundRequest')&&moonraker.includes('runControlRequest'),'non-emergency request serialization layers are incomplete');
assert(moonraker.includes("nativeRpc('printer.emergency_stop'")&&!moonraker.includes("requestScheduler.run('emergency'"),'emergency stop still waits behind the WebView request scheduler');
assert(moonraker.includes('this.configuredMoonrakerPort()===80'),'explicit port 80 is not treated as a conservative K1C endpoint');
assert(moonraker.includes("virtual_sdcard:['is_active']")&&moonraker.includes("printState!=='printing'&&printState!=='paused'"),'pre-start readiness does not re-read the live print state');
assert(moonraker.includes("secureInvoke<NativeUploadBegin>('transactional_upload_begin'")&&moonraker.includes("secureInvoke<number>('transactional_upload_chunk'")&&moonraker.includes('file.slice(offset,end).arrayBuffer()'),'source uploader is not transactional and block based');
assert(!/new FileReader[\s\S]{0,700}moonraker_upload/.test(moonraker),'source uploader still reads a complete G-code into WebView memory');
assert(analysis.includes('analyzeGCodeByteChunks')&&analysis.includes('TextDecoder'),'streaming G-code analyzer is missing');
assert(validation.includes('validateGCodeAnalysis')&&validation.includes('client.uploadedFile(filename)'),'fresh large uploads are not validated from the original File stream');

assert(queue.includes('refreshInFlight')&&queue.includes('inFlight=false')&&queue.includes('confirmed.queued_jobs[0]?.job_id')&&queue.includes('!await client.isReady()'),'queue refresh/auto-start guards are incomplete');
assert(dispatcher.includes('addChain')&&dispatcher.includes('filesRef')&&dispatcher.includes('printersRef.current.find')&&dispatcher.includes('await c.isReady()'),'dispatcher serialization or live pre-start check is missing');
assert(!dispatcher.includes('source.gcodeText(j.sourcePath)'),'dispatcher can still reconstruct a potentially huge remote file in WebView memory');
assert(local.includes('localLibraryImportBegin')&&local.includes('analyzeGCodeByteChunks')&&local.includes('client.uploadLocalLibrary')&&moonraker.includes('return await this.runFileTransfer(async active=>')&&moonraker.includes('await localLibraryUploadToPrinter(relativePath,expectedSha256,libraryId,printerId,host,defaultPort)'),'local-library native streamed path or sensitive-printer transfer guard is missing');
assert(app.includes('let stopped=false,inFlight=false,timer:number|undefined')&&app.includes('while(j.scheduledAt<=Date.now())')&&app.includes('!await c.isReady()'),'scheduler overlap/catch-up guard is missing');
assert(notifications.includes('refreshInFlight')&&notifications.includes('window.setTimeout(loop,8_000)')&&!notifications.includes('setInterval('),'notification refresh can still overlap');
assert(temperatures.includes('loadInFlight')&&temperatures.includes('window.setTimeout(loop,30_000)')&&!temperatures.includes('setInterval('),'temperature refresh can still overlap');
assert(production.includes('refreshInFlight')&&production.includes('if(refreshInFlight.current)return refreshInFlight.current'),'production library refresh can still overlap');
const updater=read('src/components/AppUpdater.tsx');
const online=read('src-tauri/src/online_updates.rs');
assert(system.includes('<AppUpdater')&&updater.includes('updateApply(info.manifestSha256)'),'in-app updater is not wired');
for(const marker of ['parse_and_verify','verify_artifact','kf_update::accept','Role::Admin','idle(&snapshots)','--proto-redir','manifest_sha256','applying.store(true'])assert(online.includes(marker),`updater safety missing: ${marker}`);

assert(/^assets\/index-[A-Za-z0-9_-]+\.js$/.test(bundlePath),'offline index does not activate the current content-hashed bundle');
for(const marker of ['printer_actor_upsert','printer_actor_rpc','printer_actor_events_pending','printer_actor_events_ack','printer_actor_reattest','transactional_upload_begin','transactional_upload_chunk','transactional_upload_finish','local_library_import_begin','local_library_read_begin','printer.emergency_stop'])assert(bundle.includes(marker),`offline bundle marker missing: ${marker}`);
for(const marker of ['update_status','update_check','update_install','update_apply','update_cancel'])assert(bundle.includes(marker),`built updater command missing: ${marker}`);
assert(!bundle.includes('local_library_read_text'),'offline bundle still reads complete local G-code into memory');
assert(!/\b(?:alert|confirm|prompt)\(/.test(bundle),'offline bundle still contains a blocking native WebView dialog');

console.log('full audit OK: actor-owned transport, durable events, safe identity and cancellable streaming paths are active');

#!/usr/bin/env node
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawn} from 'node:child_process';

const root=path.resolve(import.meta.dirname,'..');
const argument=name=>{
  const prefix=`--${name}=`;
  const inline=process.argv.find(value=>value.startsWith(prefix));
  if(inline)return inline.slice(prefix.length);
  const index=process.argv.indexOf(`--${name}`);
  return index>=0?process.argv[index+1]:undefined;
};
const delay=milliseconds=>new Promise(resolve=>setTimeout(resolve,milliseconds));
const PROBE_OUTPUT_LIMIT=2*1024*1024;
const parseProbeResponse=buffer=>{
  if(!buffer.length||buffer.length>PROBE_OUTPUT_LIMIT)throw new Error(`invalid IPC probe output size ${buffer.length}`);
  const response=JSON.parse(buffer.toString('utf8'));
  if(!response||typeof response!=='object'||typeof response.requestId!=='string'||typeof response.ok!=='boolean'){
    throw new Error('invalid IPC probe response schema');
  }
  return response;
};

if(process.argv.includes('--self-test')){
  const value={protocolVersion:4,requestId:'self-test',ok:true,data:{status:'ok'}};
  assert.deepEqual(parseProbeResponse(Buffer.from(JSON.stringify(value))),value);
  assert.throws(()=>parseProbeResponse(Buffer.alloc(0)),/output size/);
  assert.throws(()=>parseProbeResponse(Buffer.from('{}')),/response schema/);
  console.log('headless telemetry runtime harness self-test OK: native IPC probe response contract');
  process.exit(0);
}

const daemonPath=path.resolve(argument('daemon')??'');
assert.ok(daemonPath&&fs.statSync(daemonPath).isFile(),`--daemon must name a built klipper-farmd binary: ${daemonPath}`);
const probePath=path.resolve(argument('probe')??'');
assert.ok(probePath&&fs.statSync(probePath).isFile(),`--probe must name a built klipper-farm-ipc-probe binary: ${probePath}`);
const temporary=fs.mkdtempSync(path.join(os.tmpdir(),'klipper-farm-v205-telemetry-'));
const children=new Set();
const output=new Map();
const launch=(command,args,options={})=>{
  const child=spawn(command,args,{cwd:root,stdio:['ignore','pipe','pipe'],...options});
  children.add(child);
  output.set(child,[]);
  const remember=chunk=>{
    const lines=output.get(child);
    if(lines){lines.push(String(chunk));if(lines.length>80)lines.shift()}
  };
  child.stdout?.on('data',remember);
  child.stderr?.on('data',remember);
  child.once('exit',()=>children.delete(child));
  return child;
};
const childOutput=child=>(output.get(child)??[]).join('').slice(-8_000);
const waitFor=async(test,description,timeoutMs=30_000)=>{
  const deadline=Date.now()+timeoutMs;
  let lastError;
  while(Date.now()<deadline){
    try{const value=await test();if(value)return value}catch(error){if(error?.nonRetryable)throw error;lastError=error}
    await delay(100);
  }
  throw new Error(`${description} timed out${lastError?`: ${String(lastError)}`:''}`);
};
const requireChildRunning=(child,description)=>{
  if(child.exitCode===null&&child.signalCode===null)return;
  const error=new Error(`${description} exited before daemon recovery: ${child.exitCode??child.signalCode??'unknown'}${childOutput(child)?`\n${childOutput(child)}`:''}`);
  error.nonRetryable=true;
  throw error;
};
const childExited=child=>child.exitCode!==null||child.signalCode!==null;
const waitForChildExit=(child,timeoutMs)=>new Promise(resolve=>{
  if(childExited(child)){resolve(true);return}
  let settled=false;
  const finish=value=>{if(settled)return;settled=true;clearTimeout(timer);child.off('exit',onExit);resolve(value)};
  const onExit=()=>finish(true);
  const timer=setTimeout(()=>finish(childExited(child)),timeoutMs);
  child.once('exit',onExit);
});
const endpointPath=path.join(temporary,'klipper-farmd.endpoint.json');
const ipc=async(command,payload=null)=>{
  const requestId=crypto.randomBytes(16).toString('hex');
  const request={requestId,command,payload};
  const response=await new Promise((resolve,reject)=>{
    const child=spawn(probePath,['--data-dir',temporary],{
      cwd:root,
      windowsHide:true,
      stdio:['pipe','pipe','pipe'],
    });
    children.add(child);
    child.once('exit',()=>children.delete(child));
    let stdout=Buffer.alloc(0),stderr='',settled=false;
    const timeout=setTimeout(()=>finish(new Error(`IPC probe timeout for ${command}`)),command==='upload_finish'?90_000:12_000);
    const finish=(error,value)=>{
      if(settled)return;
      settled=true;
      clearTimeout(timeout);
      if(error&&child.exitCode===null)child.kill('SIGKILL');
      if(error)reject(error);else resolve(value);
    };
    child.once('error',error=>finish(new Error(`IPC probe failed to start: ${error}`)));
    child.stdout.on('data',chunk=>{
