    objectStatus.print_stats={state:'printing',filename,print_duration:0};
    objectStatus.virtual_sdcard={progress:0,is_active:true};return 'ok';
  }
  if(method==='server.webcams.list')return{webcams:[]};
  return{ok:true};
};

const pathMethod=url=>url.startsWith('/server/info')?'server.info':url.startsWith('/printer/info')?'printer.info':url.startsWith('/machine/system_info')?'machine.system_info':url.startsWith('/printer/objects/list')?'printer.objects.list':url.startsWith('/printer/objects/query')?'printer.objects.query':url.startsWith('/server/files/list')?'server.files.list':url.startsWith('/server/webcams/list')?'server.webcams.list':undefined;
const headers={'content-type':'application/json; charset=utf-8','cache-control':'no-store'};
const readBody=(request,limit=110*1024*1024)=>new Promise((resolve,reject)=>{
  const chunks=[];let size=0;
  request.on('data',chunk=>{size+=chunk.length;if(size>limit){reject(new Error('request body too large'));request.destroy();return}chunks.push(chunk)});
  request.on('end',()=>resolve(Buffer.concat(chunks)));
  request.on('error',reject);
});
const multipartValue=(body,boundary,name)=>{
  const marker=Buffer.from(`name="${name}"`),at=body.indexOf(marker);if(at<0)return undefined;
  const start=body.indexOf(Buffer.from('\r\n\r\n'),at);if(start<0)return undefined;
  const end=body.indexOf(Buffer.from(`\r\n--${boundary}`),start+4);if(end<0)return undefined;
  return body.subarray(start+4,end);
};
const multipartParts=(body,boundary)=>{
  const delimiter=Buffer.from(`--${boundary}`),separator=Buffer.from(`\r\n--${boundary}`),parts=[];
  if(!body.subarray(0,delimiter.length).equals(delimiter))throw new Error('invalid multipart opening boundary');
  let offset=delimiter.length;
  while(!body.subarray(offset,offset+2).equals(Buffer.from('--'))){
    if(!body.subarray(offset,offset+2).equals(Buffer.from('\r\n')))throw new Error('invalid multipart part separator');
    const headerEnd=body.indexOf(Buffer.from('\r\n\r\n'),offset+2);
    if(headerEnd<0)throw new Error('multipart part headers are missing');
    const partHeaders=body.toString('utf8',offset+2,headerEnd),name=partHeaders.match(/(?:^|;)\s*name="([^"]+)"/im)?.[1];
    if(!name)throw new Error('multipart field name is missing');
    const end=body.indexOf(separator,headerEnd+4);
    if(end<0)throw new Error('multipart closing boundary is missing');
    parts.push({name,filename:partHeaders.match(/(?:^|;)\s*filename="([^"\\/]+)"/im)?.[1],value:body.subarray(headerEnd+4,end)});
    offset=end+2+delimiter.length;
  }
  return parts;
};

const server=http.createServer(async(request,response)=>{
  request.on('error',error=>recordPeerError(error,request.socket,'HTTP request'));
  response.on('error',error=>recordPeerError(error,request.socket,'HTTP response'));
  requestCount++;
  if(modes.has('keep-alive')){response.shouldKeepAlive=true;response.setHeader('Connection','keep-alive')}
  if(request.url==='/emulator/state'){response.end(JSON.stringify({printStartCount,uploadCount,uploadAttemptCount,downloadCount,moveCount,jsonRpcHttpCount,restMoveCount,uploadRequests,files:[...remoteFiles.keys()]}));return}
  if(request.method==='POST'&&request.url?.startsWith('/emulator/upload-behavior')){
    uploadBehavior=new URL(request.url,'http://127.0.0.1').searchParams.get('mode')||'normal';
    response.end(JSON.stringify({uploadBehavior}));return;
  }
  if(request.method==='POST'&&request.url?.startsWith('/emulator/start-behavior')){
    acknowledgeStartOnly=new URL(request.url,'http://127.0.0.1').searchParams.get('mode')==='ack-only';
    objectStatus.print_stats={state:'standby',filename:'',print_duration:0};
    objectStatus.virtual_sdcard={progress:0,is_active:false};
    response.end(JSON.stringify({acknowledgeStartOnly}));return;
  }
  if(request.url?.startsWith('/server/files/gcodes/')){
    const filename=decodeURIComponent(request.url.slice('/server/files/gcodes/'.length).split('?')[0]),item=remoteFiles.get(filename);
    if(!item?.bytes){response.writeHead(404,headers);response.end('{}');return}
    downloadCount++;
    response.writeHead(200,{'content-type':'application/octet-stream','content-length':String(item.bytes.length)});response.end(item.bytes);return;
  }
  if(delayMs)await sleep(delayMs);
  if(disconnectAfter&&requestCount>=disconnectAfter||modes.has('disconnect')){request.socket.destroy();return}
  if(modes.has('ws-only')){response.writeHead(404,headers);response.end(JSON.stringify({error:'REST disabled by emulator'}));return}
  if(!apiKeyAccepted(request)){response.writeHead(401,headers);response.end(JSON.stringify({error:{message:'Unauthorized'}}));return}
  if(modes.has('404')){response.writeHead(404,headers);response.end(JSON.stringify({error:{message:'Not found'}}));return}
  if(request.method==='POST'&&request.url==='/server/jsonrpc'){
    jsonRpcHttpCount++;
    if(modes.has('nexusp')){response.writeHead(404,headers);response.end(JSON.stringify({error:{code:404,message:'Method not found'}}));return}
  }
  if(modes.has('nexusp')&&request.method==='POST'&&request.url?.startsWith('/printer/objects/query')){
    response.writeHead(405,headers);response.end(JSON.stringify({error:{message:'GET query required'}}));return;
  }
  if(request.method==='POST'&&request.url?.startsWith('/server/files/move')){
    restMoveCount++;
    if(modes.has('legacy-upload')){response.writeHead(404,headers);response.end(JSON.stringify({error:{message:'file move is unsupported by this legacy server'}}));return}
    try{
      const query=new URL(request.url,'http://127.0.0.1').searchParams;
      const params={source:query.get('source'),dest:query.get('dest')};
      if(!params.source||!params.dest)throw new Error('source and dest query arguments required');
      response.writeHead(200,headers);response.end(JSON.stringify({result:rpcResult('server.files.move',params)}));return;
    }catch(error){response.writeHead(400,headers);response.end(JSON.stringify({error:{message:String(error.message||error)}}));return}
  }
  if(request.method==='POST'&&request.url?.startsWith('/printer/print/start')){
    try{
      const filename=new URL(request.url,'http://127.0.0.1').searchParams.get('filename');
      response.writeHead(200,headers);response.end(JSON.stringify({result:rpcResult('printer.print.start',{filename})}));return;
    }catch(error){response.writeHead(400,headers);response.end(JSON.stringify({error:{message:String(error.message||error)}}));return}
  }
  if(modes.has('disk-full')&&request.url?.startsWith('/server/files/upload')){response.writeHead(507,headers);response.end(JSON.stringify({error:{message:'No space left on device'}}));return}
  if(request.method==='POST'&&request.url?.startsWith('/server/files/upload')){
    uploadAttemptCount++;
    try{
      const contentType=String(request.headers['content-type']||''),boundary=contentType.match(/boundary=([^;]+)/i)?.[1];
      if(!boundary)throw new Error('multipart boundary is missing');
      const body=await readBody(request),parts=multipartParts(body,boundary),filePart=parts.find(part=>part.name==='file');
      const file=filePart?.value,filename=filePart?.filename,checksum=multipartValue(body,boundary,'checksum')?.toString('utf8').trim();
      if(!file||!filename)throw new Error('multipart file is missing');
      const actual=crypto.createHash('sha256').update(file).digest('hex');
      uploadRequests.push({filename,fields:parts.map(part=>part.name),boundary,size:file.length,sha256:actual});
      if(uploadRequests.length>20)uploadRequests.shift();
      if(modes.has('legacy-upload')&&(parts.length!==2||parts[0].name!=='file'||parts[1].name!=='root'||parts[1].value.toString('utf8')!=='gcodes')){response.writeHead(500,headers);response.end(JSON.stringify({error:{message:'upload file fail: unsupported legacy fields; requires only file then root=gcodes'}}));return}
      if(uploadBehavior==='generic-500'){response.writeHead(500,headers);response.end(JSON.stringify({error:{message:'simulated upload server failure'}}));return}
      if(checksum&&(checksum.toLowerCase()!==actual||uploadBehavior!=='normal')){response.writeHead(422,headers);response.end(JSON.stringify({error:{code:422,message:`File checksum mismatch: expected ${checksum}, calculated ${'0'.repeat(64)}`}}));return}
      const stored=Buffer.from(file);if(uploadBehavior==='checksum-refusal-corrupt'||uploadBehavior==='corrupt-bytes')stored[0]^=1;
      uploadCount++;remoteFiles.set(filename,{size:file.length,sha256:actual,modified:Date.now()/1000,bytes:stored});
      response.writeHead(201,headers);response.end(JSON.stringify({result:{item:{path:filename,root:'gcodes',size:file.length}}}));return;
    }catch(error){response.writeHead(400,headers);response.end(JSON.stringify({error:{message:String(error.message||error)}}));return}
  }
  if(request.method==='GET'&&request.url?.startsWith('/server/files/metadata')){
    const url=new URL(request.url,'http://127.0.0.1'),filename=cleanRemote(url.searchParams.get('filename')),item=remoteFiles.get(filename);
    if(!item){response.writeHead(404,headers);response.end(JSON.stringify({error:{message:'file not found'}}));return}
    response.writeHead(200,headers);response.end(JSON.stringify({result:{size:item.size,sha256:item.sha256,modified:item.modified,filename}}));return;
  }
  if(request.method==='POST'&&request.url?.startsWith('/server/jsonrpc')){
    try{
      const message=JSON.parse((await readBody(request,2*1024*1024)).toString('utf8'));
      const result=rpcResult(message.method,message.params??{});
      response.writeHead(200,headers);response.end(JSON.stringify({jsonrpc:'2.0',id:message.id,result}));return;
    }catch(error){response.writeHead(200,headers);response.end(JSON.stringify({jsonrpc:'2.0',error:{code:-32603,message:String(error.message||error)}}));return}
  }
  const method=pathMethod(request.url||'');
  if(!method){response.writeHead(404,headers);response.end(JSON.stringify({error:{message:'Unknown emulator route'}}));return}
  if(modes.has('corrupt')){response.writeHead(200,headers);response.end('{"result":');return}
  response.writeHead(200,headers);response.end(JSON.stringify({result:rpcResult(method)}));
});

const expectedPeerDisconnect=error=>['ECONNRESET','EPIPE','ECONNABORTED','ERR_STREAM_DESTROYED'].includes(error?.code);
let fatalClosing=false;
const recordPeerError=(error,socket,context)=>{
  if(expectedPeerDisconnect(error)){peerResetCount++;return}
  unexpectedSocketErrors++;
  process.stderr.write(`emulator unexpected socket error (${context}): ${String(error?.stack||error)}\n`);
  if(fatalClosing)return;
  fatalClosing=true;
  process.exitCode=1;
  socket?.destroy();
  for(const active of websocketSockets)active.destroy();
  server.close(()=>process.exit(1));
  server.closeAllConnections?.();
  setTimeout(()=>process.exit(1),1_000).unref();
};
server.on('clientError',(error,socket)=>{
  recordPeerError(error,socket,'HTTP client');
  socket.destroy();
});
server.on('error',error=>recordPeerError(error,undefined,'HTTP server'));

const websocketAccept=key=>crypto.createHash('sha1').update(`${key}258EAFA5-E914-47DA-95CA-C5AB0DC85B11`).digest('base64');
const websocketFrame=value=>{
  const payload=Buffer.from(JSON.stringify(value));
  if(payload.length<126)return Buffer.concat([Buffer.from([0x81,payload.length]),payload]);
  const header=Buffer.alloc(4);header[0]=0x81;header[1]=126;header.writeUInt16BE(payload.length,2);return Buffer.concat([header,payload]);
};
const decodeFrames=buffer=>{
  const frames=[];let offset=0;
  while(offset+2<=buffer.length){const second=buffer[offset+1],masked=!!(second&0x80);let size=second&0x7f,header=2;if(size===126){if(offset+4>buffer.length)break;size=buffer.readUInt16BE(offset+2);header=4}else if(size===127)break;const maskSize=masked?4:0;if(offset+header+maskSize+size>buffer.length)break;const mask=masked?buffer.subarray(offset+header,offset+header+4):undefined,payload=Buffer.from(buffer.subarray(offset+header+maskSize,offset+header+maskSize+size));if(mask)for(let i=0;i<payload.length;i++)payload[i]^=mask[i%4];frames.push(payload);offset+=header+maskSize+size}
  return{frames,remaining:buffer.subarray(offset)};
};

server.on('upgrade',(request,socket)=>{
  connectionCount++;
  websocketSockets.add(socket);
  let closed=false;
  const onSocketError=error=>{closed=true;recordPeerError(error,socket,'WebSocket peer')};
  socket.on('error',onSocketError);
  socket.on('close',()=>{closed=true;websocketSockets.delete(socket)});
  const safeWrite=data=>{
    if(closed||socket.destroyed||!socket.writable)return false;
    try{return socket.write(data)}catch(error){onSocketError(error);return false}
  };
  if(!apiKeyAccepted(request)){safeWrite('HTTP/1.1 401 Unauthorized\r\nConnection: close\r\n\r\n');socket.destroy();return}
  if(modes.has('rest-only')||modes.has('404')){safeWrite('HTTP/1.1 404 Not Found\r\nConnection: close\r\n\r\n');socket.destroy();return}
  const key=request.headers['sec-websocket-key'];if(typeof key!=='string'){socket.destroy();return}
  safeWrite(`HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: ${websocketAccept(key)}\r\n\r\n`);
  let pending=Buffer.alloc(0),notificationSequence=0;
  const writeMessage=(message,{notification=false}={})=>{
    if(notification&&dropEvery&&++notificationSequence%dropEvery===0)return;
    const frame=websocketFrame(message);safeWrite(frame);
    if(notification&&modes.has('duplicate'))safeWrite(frame);
  };
  const emitStatusFaults=async()=>{
    const base=Date.now()/1000;
    const events=[
      {jsonrpc:'2.0',method:'notify_status_update',params:[{print_stats:{state:'standby'}},base+1]},
      {jsonrpc:'2.0',method:'notify_status_update',params:[{extruder:{temperature:24.4}},base+(modes.has('event-gap')?45:2)]},
    ];
    if(modes.has('stale-event'))events.push({jsonrpc:'2.0',method:'notify_status_update',params:[{heater_bed:{temperature:99}},base-.5]});
    if(modes.has('reorder'))events.reverse();
    for(const event of events){await sleep(Math.max(2,Math.min(50,delayMs)));writeMessage(event,{notification:true})}
  };
  socket.on('data',async data=>{
    pending=Buffer.concat([pending,data]);const decoded=decodeFrames(pending);pending=decoded.remaining;
    for(const payload of decoded.frames){
      requestCount++;
      if(delayMs)await sleep(delayMs);
      if(disconnectAfter&&requestCount>=disconnectAfter||modes.has('disconnect')){socket.destroy();return}
      let message;try{message=JSON.parse(payload.toString('utf8'))}catch{continue}
      if(message.method==='server.connection.identify')continue;
      if(modes.has('corrupt')){safeWrite(Buffer.from([0x81,5,0x7b,0x22,0x78,0x22,0x3a]));continue}
      try{
        writeMessage({jsonrpc:'2.0',id:message.id,result:rpcResult(message.method,message.params??{})});
        if(message.method==='printer.objects.subscribe')void emitStatusFaults();
      }catch(error){writeMessage({jsonrpc:'2.0',id:message.id,error:{code:-32603,message:String(error.message||error)}})}
    }
  });
});

const resetWebSocketPeer=listeningPort=>new Promise((resolve,reject)=>{
  const socket=net.createConnection({host,port:listeningPort});
  const timer=setTimeout(()=>{socket.destroy();reject(new Error('reset self-test WebSocket handshake timed out'))},5_000);
  let headers='';
  socket.on('connect',()=>socket.write(
    `GET /websocket HTTP/1.1\r\nHost: ${host}:${listeningPort}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Version: 13\r\nSec-WebSocket-Key: ${crypto.randomBytes(16).toString('base64')}\r\n\r\n`,
  ));
  socket.on('data',chunk=>{
    headers+=chunk.toString('latin1');
    if(!headers.includes('\r\n\r\n'))return;
    clearTimeout(timer);
    if(!headers.startsWith('HTTP/1.1 101')){socket.destroy();reject(new Error(`reset self-test handshake failed: ${headers.split('\r\n')[0]}`));return}
    socket.resetAndDestroy();
    resolve();
  });
  socket.on('error',error=>{
    if(expectedPeerDisconnect(error)&&headers.startsWith('HTTP/1.1 101'))return;
    clearTimeout(timer);reject(error);
  });
});
const requestHealth=listeningPort=>new Promise((resolve,reject)=>{
  const request=http.get({host,port:listeningPort,path:'/server/info'},response=>{
    response.resume();
    response.on('end',()=>response.statusCode===200?resolve():reject(new Error(`reset self-test health returned ${response.statusCode}`)));
  });
  request.setTimeout(5_000,()=>request.destroy(new Error('reset self-test health timed out')));
  request.on('error',reject);
});
const runResetSelfTest=async listeningPort=>{
  await resetWebSocketPeer(listeningPort);
  await sleep(200);
  await requestHealth(listeningPort);
  if(unexpectedSocketErrors)throw new Error(`unexpected socket errors: ${unexpectedSocketErrors}`);
  process.stdout.write(`hardware emulator reset self-test OK: peer_resets=${peerResetCount}\n`);
  for(const socket of websocketSockets)socket.destroy();
  server.close(()=>process.exit(0));
  server.closeAllConnections?.();
};

server.listen(port,host,()=>{
  const address=server.address();
  const listeningPort=typeof address==='object'&&address?address.port:port;
  process.stdout.write(`Klipper Farm hardware emulator: model=${model} host=${host} port=${listeningPort} mode=${[...modes].join(',')} delay=${delayMs}ms dropEvery=${dropEvery}\n`);
  if(resetSelfTest)void runResetSelfTest(listeningPort).catch(error=>recordPeerError(error,undefined,'reset self-test'));
});
const close=()=>{
  for(const socket of websocketSockets)socket.destroy();
  server.close(()=>process.exit(process.exitCode??0));
  server.closeAllConnections?.();
};
process.on('SIGINT',close);process.on('SIGTERM',close);
process.on('exit',()=>process.stderr.write(`emulator summary: requests=${requestCount} websocket_connections=${connectionCount} peer_resets=${peerResetCount} unexpected_socket_errors=${unexpectedSocketErrors}\n`));

