type LocalAction={kind:'start'|'queue'|'blocked'|'delete';entry:LocalLibraryEntry;report?:GCodeValidation;sha256?:string;targetKey?:string};
type ImportProgress={done:number;total:number;stored:number;skipped:number;current:string};
type FolderDelete={path:string;name:string;files:number;size:number};

const targetKey=(printer:PrinterModel)=>JSON.stringify([printer.id,printer.host,printer.profile,printer.modelSelection]);
const MAX_IMPORT_FILES=5_000;
const MAX_FILE_SIZE=100*1024*1024;
const leafName=(path:string)=>path.split('/').filter(Boolean).at(-1)??path;
const parentPath=(path:string)=>path.split('/').slice(0,-1).join('/');
const filesLabel=(value:number)=>{
  const lastTwo=value%100,last=value%10;
  return lastTwo>=11&&lastTwo<=14?'файлов':last===1?'файл':last>=2&&last<=4?'файла':'файлов';
};
const bytes=(value:number)=>{
  if(value<1024)return `${value} Б`;
  if(value<1024*1024)return `${(value/1024).toFixed(1)} КБ`;
  if(value<1024*1024*1024)return `${(value/1024/1024).toFixed(1)} МБ`;
  return `${(value/1024/1024/1024).toFixed(2)} ГБ`;
};
const date=(value?:number)=>value?new Date(value).toLocaleString('ru-RU'):'дата не указана';

const abortError=(message='Операция отменена')=>{const error=new Error(message);error.name='AbortError';return error};
const ensureActive=(signal?:AbortSignal)=>{if(signal?.aborted)throw abortError()};

const importLocalFile=async(printerId:string,relativePath:string,file:File,overwrite:boolean,signal?:AbortSignal)=>{
  ensureActive(signal);
  const started=await localLibraryImportBegin(printerId,relativePath,file.size,overwrite);
  if(started.result)return started.result;
  if(!started.importId)throw new Error('Локальный импорт не создал сессию передачи');
  const chunkSize=Math.max(64*1024,Math.min(512*1024,Math.trunc(started.chunkSize)||512*1024));
  let offset=0,finished=false;
  try{
    while(offset<file.size){
      ensureActive(signal);
      const end=Math.min(file.size,offset+chunkSize);
      const data=Array.from(new Uint8Array(await file.slice(offset,end).arrayBuffer()));
      ensureActive(signal);
      const received=await localLibraryImportChunk(started.importId,offset,data);
      if(received!==end)throw new Error('Локальное хранилище подтвердило неверный размер блока');
      offset=end;
    }
    const result=await localLibraryImportFinish(started.importId);
    finished=true;
    return result;
  }finally{if(!finished)await localLibraryImportAbort(started.importId).catch(()=>false)}
};

const analyzeLocalFile=async(printerId:string,relativePath:string,signal?:AbortSignal)=>{
  ensureActive(signal);
  const started=await localLibraryReadBegin(printerId,relativePath);
  let offset=0,finished=false,sha256='';
  const chunks=async function*(){
    while(!finished){
      ensureActive(signal);
      const chunk=await localLibraryReadChunk(started.readId,offset);
      if(chunk.nextOffset<=offset||chunk.nextOffset>started.size)throw new Error('Нарушен порядок чтения локального G-code');
      offset=chunk.nextOffset;
      if(chunk.data.length)yield Uint8Array.from(chunk.data);
      if(chunk.done){
        if(offset!==started.size||!chunk.sha256)throw new Error('Локальный G-code прочитан не полностью');
        sha256=chunk.sha256;
        finished=true;
      }
    }
  };
  try{
    const analysis=await analyzeGCodeByteChunks(chunks(),signal);
    if(!finished||!sha256)throw new Error('Проверка локального G-code не завершена');
    return{analysis,sha256};
  }finally{if(!finished)await localLibraryReadAbort(started.readId).catch(()=>false)}
};

function LocalTransferStatus({transfer,launching,cancelRequested,queue,cancel}:{transfer:LocalTransferProgress&{startedAt:number};launching:boolean;cancelRequested:boolean;queue:boolean;cancel:()=>void}){
  const now=useLiveNow();
  return <div className="printerFileTransfer" role="status" aria-live="polite">
    <div><RefreshCw className="spin"/><strong>{cancelRequested?'Действие отменено. Ожидаем завершения передачи…':launching?(queue?'Добавляем в очередь…':'Ожидаем подтверждения запуска…'):transfer.phase==='preparing'?'Подготавливаем файл…':'Передаём проверенный файл на принтер…'}</strong><span>{Math.max(0,Math.floor((now-transfer.startedAt)/1000))} с</span></div>
    {!cancelRequested&&!launching&&transfer.phase==='preparing'&&<><progress max={transfer.total} value={transfer.done}/><small>{bytes(transfer.done)} / {bytes(transfer.total)}</small></>}
    {!launching&&transfer.phase==='sending'&&<small>Передачу файла нельзя прервать. Отмена запретит {queue?'добавление в очередь':'запуск печати'} после её завершения.</small>}
    {!launching&&<button type="button" disabled={cancelRequested} onClick={cancel}><X/>{cancelRequested?'Отмена запрошена':'Отменить действие'}</button>}
  </div>;
}

export function LocalLibraryPanel({
  printer,
  libraryScopeId,
  libraryScopeLabel,
  librarySharedByModel,
  sourcePrinterIds,
  client,
  canOperate,
  canSync,
  onPrinted,
}:{
  printer:PrinterModel;
  libraryScopeId:string;
  libraryScopeLabel:string;
  librarySharedByModel:boolean;
  sourcePrinterIds:string[];
  client?:MoonrakerClient;
  canOperate:boolean;
  canSync:boolean;
  onPrinted:()=>void;
}){
  const printerRef=useRef(printer);printerRef.current=printer;
  const permissionsRef=useRef({canOperate,canSync});permissionsRef.current={canOperate,canSync};
  const [transfer,setTransfer]=useState<(LocalTransferProgress&{startedAt:number})|undefined>();
  const [launching,setLaunching]=useState(false);
  const [cancelRequested,setCancelRequested]=useState(false);
  const [launchUnconfirmed,setLaunchUnconfirmed]=useState(false);
  const cancelTransfer=()=>{if(launching||!operationAbort.current)return;setCancelRequested(true);operationAbort.current.abort('Передача отменена пользователем')};
  const [entries,setEntries]=useState<LocalLibraryEntry[]>([]);
  const [legacy,setLegacy]=useState({files:0,size:0});
  const [folder,setFolder]=useState('');
  const [query,setQuery]=useState('');
  const [busy,setBusy]=useState(false);
  const [error,setError]=useState('');
  const [notice,setNotice]=useState('');
  const [overwrite,setOverwrite]=useState(false);
  const [importProgress,setImportProgress]=useState<ImportProgress>();
  const [action,setAction]=useState<LocalAction>();
  const [folderDelete,setFolderDelete]=useState<FolderDelete>();
  const [operation,setOperation]=useState<'import'|'analysis'|'upload'>();
  const operationAbort=useRef<AbortController>();
  const refreshRequest=useRef(0);
  const scopeIdRef=useRef(libraryScopeId);
  scopeIdRef.current=libraryScopeId;
  const sourceScopeKey=sourcePrinterIds.join('|');
  useModalAccessibility(()=>{if(busy){if(operation==='upload')cancelTransfer();return}setAction(undefined);setFolderDelete(undefined);setError('');setLaunchUnconfirmed(false)},'.localLibrary .printerFileDialog','Действие с локальным файлом',!!action||!!folderDelete);

  const loadScope=useCallback(async(migrate=false)=>{
    const scopeId=libraryScopeId;
    const request=++refreshRequest.current;
    setBusy(true);
    setError('');
    let migrationError='';
    try{
      if(migrate&&canOperate&&librarySharedByModel){
        try{
          const sourceIds=sourcePrinterIds.filter(id=>id!==scopeId);
          if(sourceIds.length){
            const merged=await localLibraryMergeScopes(sourceIds,scopeId);
            if(request!==refreshRequest.current||scopeId!==scopeIdRef.current)return;
            if(merged.moved||merged.duplicates){
              const renamed=merged.renamed?` Из-за совпадающих имён ${merged.renamed} ${filesLabel(merged.renamed)} помещено в папку «Объединено из другого принтера».`:'';
              setNotice(`Старые библиотеки принтеров ${libraryScopeLabel} объединены: ${merged.moved} перенесено, ${merged.duplicates} дублей убрано.${renamed}`);
            }
            if(merged.conflicts)migrationError=`Не удалось безопасно объединить ${merged.conflicts} ${filesLabel(merged.conflicts)}. Они оставлены в прежних каталогах без удаления.`;
          }
        }catch(value){migrationError=`Общая библиотека открыта, но перенос старых файлов не завершён: ${String(value instanceof Error?value.message:value)}`}
      }
      const result=await localLibraryList(scopeId);
      if(request!==refreshRequest.current||scopeId!==scopeIdRef.current)return;
      setEntries(result.files);
      setLegacy({files:result.legacyFiles,size:result.legacySize});
      if(migrationError)setError(migrationError);
    }
    catch(value){if(request===refreshRequest.current&&scopeId===scopeIdRef.current)setError(String(value instanceof Error?value.message:value))}
    finally{if(request===refreshRequest.current&&scopeId===scopeIdRef.current)setBusy(false)}
  },[libraryScopeId,libraryScopeLabel,librarySharedByModel,sourceScopeKey,canOperate]);

  const refresh=useCallback(()=>loadScope(false),[loadScope]);

  useEffect(()=>{
    operationAbort.current?.abort('Смена локальной библиотеки');
    refreshRequest.current++;
    setEntries([]);setLegacy({files:0,size:0});setFolder('');setQuery('');setBusy(false);setError('');setNotice('');setAction(undefined);setFolderDelete(undefined);setImportProgress(undefined);setTransfer(undefined);setLaunching(false);setCancelRequested(false);setLaunchUnconfirmed(false);
    return()=>{operationAbort.current?.abort('Локальная библиотека закрыта');refreshRequest.current++};
  },[libraryScopeId,printer.id,printer.host]);
  useEffect(()=>{void loadScope(true)},[loadScope]);

  const folderRows=useMemo(()=>{
    if(query.trim())return [];
    const prefix=folder?`${folder}/`:'';
    const map=new Map<string,{path:string;name:string;files:number;size:number}>();
    for(const entry of entries){
      if(!entry.path.startsWith(prefix))continue;
      const rest=entry.path.slice(prefix.length),separator=rest.indexOf('/');
      if(separator<0)continue;
      const name=rest.slice(0,separator),path=prefix+name,current=map.get(path)??{path,name,files:0,size:0};
      current.files++;current.size+=entry.size;map.set(path,current);
    }
    return [...map.values()].sort((left,right)=>left.name.localeCompare(right.name,undefined,{numeric:true,sensitivity:'base'}));
  },[entries,folder,query]);

  const visibleFiles=useMemo(()=>{
    const search=query.trim().toLowerCase(),prefix=folder?`${folder}/`:'';
    return entries.filter(entry=>{
      if(search)return entry.path.toLowerCase().includes(search);
      if(!entry.path.startsWith(prefix))return false;
      return !entry.path.slice(prefix.length).includes('/');
    }).sort((left,right)=>leafName(left.path).localeCompare(leafName(right.path),undefined,{numeric:true,sensitivity:'base'}));
  },[entries,folder,query]);

  const breadcrumbs=useMemo(()=>{
    const output:Array<{name:string;path:string}>=[];
    let current='';
    for(const segment of folder.split('/').filter(Boolean)){
      current=current?`${current}/${segment}`:segment;
      output.push({name:segment,path:current});
    }
    return output;
  },[folder]);

  const totalSize=useMemo(()=>entries.reduce((sum,entry)=>sum+entry.size,0),[entries]);
  const totalFolders=useMemo(()=>new Set(entries.flatMap(entry=>{
    const parts=entry.path.split('/').slice(0,-1),paths:string[]=[];
    for(let index=1;index<=parts.length;index++)paths.push(parts.slice(0,index).join('/'));
    return paths;
  })).size,[entries]);

  const importSelection=async(files:File[],mode:'folder'|'file')=>{
    if(!canOperate||busy)return;
    const scopeId=libraryScopeId;
    const accepted=files.filter(file=>/\.(?:gcode|gco)$/i.test(file.name));
    const oversized=accepted.filter(file=>file.size===0||file.size>MAX_FILE_SIZE);
    if(accepted.length>MAX_IMPORT_FILES){setError(`В одной операции можно импортировать не более ${MAX_IMPORT_FILES} G-code файлов.`);return}
    if(oversized.length){setError(`${oversized.length} файлов пустые или превышают лимит 100 MiB. Импорт отменён — исправьте набор и повторите.`);return}
    if(!accepted.length){setError(mode==='folder'?'В выбранной папке нет файлов .gcode или .gco.':'Выберите один файл .gcode или .gco.');return}
    setBusy(true);setError('');setNotice('');
    const controller=new AbortController();operationAbort.current=controller;setOperation('import');
    let stored=0,skipped=0,done=0;
    setImportProgress({done,total:accepted.length,stored,skipped,current:''});
    try{
      for(const file of accepted){
        if(scopeId!==scopeIdRef.current)return;
        const relativePath=mode==='file'?(folder?`${folder}/${file.name}`:file.name):(file.webkitRelativePath||file.name);
        setImportProgress({done,total:accepted.length,stored,skipped,current:relativePath});
        const result=await importLocalFile(scopeId,relativePath,file,overwrite,controller.signal);
        if(scopeId!==scopeIdRef.current)return;
        if(result.status==='skipped')skipped++;else stored++;
        done++;
        setImportProgress({done,total:accepted.length,stored,skipped,current:relativePath});
      }
      await audit(mode==='folder'?'local_library.folder_import':'local_library.file_import',`${printer.name} · ${stored} сохранено · ${skipped} пропущено`);
      if(scopeId!==scopeIdRef.current)return;
      await refresh();
      if(scopeId!==scopeIdRef.current)return;
      setNotice(mode==='folder'
        ?`Импорт завершён: ${stored} сохранено, ${skipped} совпадений пропущено. Структура папок сохранена и доступна офлайн.`
        :`${stored?'Файл сохранён':'Совпадающий файл пропущен'} в «${folder||'Моя флешка'}» для ${libraryScopeLabel}.`);
    }catch(value){if(scopeId===scopeIdRef.current)setError(value instanceof Error&&value.name==='AbortError'?`Импорт отменён после ${done} из ${accepted.length}.`:`Импорт остановлен после ${done} из ${accepted.length}: ${String(value instanceof Error?value.message:value)}`)}
    finally{if(operationAbort.current===controller)operationAbort.current=undefined;if(scopeId===scopeIdRef.current){setOperation(undefined);setBusy(false);window.setTimeout(()=>setImportProgress(undefined),1200)}}
  };

  const chooseFolder=(event:ChangeEvent<HTMLInputElement>)=>{
    const selected=Array.from(event.currentTarget.files??[]);
    event.currentTarget.value='';
    void importSelection(selected,'folder');
  };

  const chooseFile=(event:ChangeEvent<HTMLInputElement>)=>{
    const selected=Array.from(event.currentTarget.files??[]).slice(0,1);
    event.currentTarget.value='';
    void importSelection(selected,'file');
  };

  const prepare=async(entry:LocalLibraryEntry,kind:'start'|'queue')=>{
    if(!canOperate||!client||!canSync||busy||operationAbort.current)return;
    const scopeId=libraryScopeId;
    setBusy(true);setError('');setNotice('');
    const controller=new AbortController();operationAbort.current=controller;setOperation('analysis');
    try{
      const {analysis,sha256}=await analyzeLocalFile(scopeId,entry.path,controller.signal);
      if(scopeId!==scopeIdRef.current)return;
      const report=validateGCodeAnalysis(printer,entry.path,analysis);
      if(!report.ok)await audit('local_library.preflight_blocked',`${entry.path} → ${printer.name}`);
      if(scopeId!==scopeIdRef.current)return;
      ensureActive(controller.signal);
      setLaunchUnconfirmed(false);
      setAction({kind:report.ok?kind:'blocked',entry,report,sha256,targetKey:targetKey(printer)});
    }catch(value){if(scopeId===scopeIdRef.current)setError(value instanceof Error&&value.name==='AbortError'?'Проверка G-code отменена пользователем.':`Полная проверка не выполнена: ${String(value instanceof Error?value.message:value)}`)}
    finally{if(operationAbort.current===controller)operationAbort.current=undefined;if(scopeId===scopeIdRef.current){setOperation(undefined);setBusy(false)}}
  };

  const confirmAction=async()=>{
    const current=action;
    if(!current||current.kind==='blocked'||!canOperate||busy||operationAbort.current||launchUnconfirmed)return;
    const scopeId=libraryScopeId;
    setBusy(true);setError('');setCancelRequested(false);setLaunching(false);
    const controller=new AbortController();operationAbort.current=controller;
    let commandSent=false;
    const ensureTarget=()=>{
      ensureActive(controller.signal);
      if(scopeId!==scopeIdRef.current||current.targetKey!==targetKey(printerRef.current))throw new Error('Принтер или его настройки изменились. Проверьте файл заново');
      if(!permissionsRef.current.canOperate||!permissionsRef.current.canSync)throw new Error('Связь с принтером потеряна. Файл остаётся в библиотеке');
      if(current.kind==='start'&&(printerRef.current.status.state!=='ready'||printerRef.current.status.connectionState!=='online'))throw new Error('Принтер больше не готов к запуску. Файл остаётся в библиотеке');
      assertModelDependentOperationAllowed(printerRef.current);
    };
    try{
      if(current.kind==='delete'){
        await localLibraryDelete(scopeId,current.entry.path);
        ensureActive(controller.signal);
        if(scopeId!==scopeIdRef.current)return;
        setEntries(items=>items.filter(item=>item.path!==current.entry.path));
        setAction(undefined);setNotice(`${current.entry.path} удалён из локальной библиотеки.`);return;
      }
      if(!client||!current.report?.ok||!current.sha256)throw new Error('Проверка файла не завершена. Файл остаётся в библиотеке');
      ensureTarget();
      setOperation('upload');
      const startedAt=Date.now();setTransfer({phase:'preparing',done:0,total:current.entry.size,startedAt});
      const remotePath=await client.uploadLocalLibrary(current.entry.path,current.sha256,scopeId,progress=>{
        if(!controller.signal.aborted&&operationAbort.current===controller)setTransfer({...progress,startedAt});
      },controller.signal);
      ensureTarget();
      setLaunching(true);commandSent=true;
      if(current.kind==='queue'){
        await client.enqueue([remotePath]);
        if(scopeId!==scopeIdRef.current||operationAbort.current!==controller)return;
        setAction(undefined);setNotice(`${current.entry.path} проверен, скопирован на ${printerDisplayName(printer)} и добавлен в очередь.`);
        void audit('print.queue_add',`${current.entry.path} → ${remotePath} → ${printer.name}`).catch(()=>{});return;
      }
      await client.start(remotePath,printStartOptionsFromValidation(current.report));
      if(scopeId!==scopeIdRef.current||operationAbort.current!==controller)return;
      setAction(undefined);onPrinted();
      void audit('print.validated_start',`${current.entry.path} → ${remotePath} → ${printer.name}`).catch(()=>{});
    }catch(value){
      if(scopeId===scopeIdRef.current&&operationAbort.current===controller){
        if(commandSent){setLaunchUnconfirmed(true);setError(`Команда отправлена, но подтверждение не получено. Проверьте состояние принтера перед повторным запуском. ${String(value instanceof Error?value.message:value)}`)}
        else setError(value instanceof Error&&value.name==='AbortError'?'Действие отменено; команда запуска или добавления в очередь не отправлялась. Файл мог остаться на принтере.':String(value instanceof Error?value.message:value));
      }
    }finally{
      if(operationAbort.current===controller){operationAbort.current=undefined;setOperation(undefined);setTransfer(undefined);setLaunching(false);setCancelRequested(false);setBusy(false)}
    }
  };

