      const result=await localLibraryDeleteDirectory(scopeId,current.path);
      if(scopeId!==scopeIdRef.current)return;
      const prefix=`${current.path}/`;
      setEntries(items=>items.filter(item=>item.path!==current.path&&!item.path.startsWith(prefix)));
      if(folder===current.path||folder.startsWith(prefix))setFolder(parentPath(current.path));
