      setNotice(`Папка «${current.name}» удалена из библиотеки ${libraryScopeLabel}: ${result.files} ${filesLabel(result.files)}, ${bytes(result.size)}.`);
    }catch(value){if(scopeId===scopeIdRef.current)setError(`Папка не удалена: ${String(value instanceof Error?value.message:value)}`)}
    finally{if(scopeId===scopeIdRef.current)setBusy(false)}
